<?php
class Location extends Model{public function all(){return $this->query('SELECT * FROM locations ORDER BY location_id DESC')->fetchAll();}public function find($id){return $this->query('SELECT * FROM locations WHERE location_id=?',[$id])->fetch();}public function create($d){return $this->query('INSERT INTO locations(district,city,postcode,transport_zone,is_popular) VALUES(?,?,?,?,?)',[$d['district'],$d['city'],$d['postcode'],$d['transport_zone'],$d['is_popular']]);}public function update($id,$d){return $this->query('UPDATE locations SET district=?,city=?,postcode=?,transport_zone=?,is_popular=? WHERE location_id=?',[$d['district'],$d['city'],$d['postcode'],$d['transport_zone'],$d['is_popular'],$id]);}public function delete($id){return $this->query('DELETE FROM locations WHERE location_id=?',[$id]);}}
